import{_ as t,o,c as a,ah as s}from"./chunks/framework.Bja9t6Wf.js";const u=JSON.parse('{"title":"Research: Patronage & Chats (The Schmid System)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/postenschacher.md","filePath":"en/recherche/postenschacher.md"}'),r={name:"en/recherche/postenschacher.md"};function h(i,e,n,c,l,m){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="research-patronage-chats-the-schmid-system" tabindex="-1">Research: Patronage &amp; Chats (The Schmid System) <a class="header-anchor" href="#research-patronage-chats-the-schmid-system" aria-label="Permalink to &quot;Research: Patronage &amp; Chats (The Schmid System)&quot;">​</a></h1><p><strong>&quot;Kriegst eh alles, was du willst&quot; – The digital protocols of power.</strong></p><p>The securing of the mobile phone of former ÖBAG boss Thomas Schmid provided unprecedented insights into the inner workings of Austrian power politics. For our mockumentary, these chats are the &quot;modern archive&quot; that replaces the paper files of the 1930s.</p><hr><h2 id="the-thomas-schmid-chats" tabindex="-1">The Thomas Schmid Chats <a class="header-anchor" href="#the-thomas-schmid-chats" aria-label="Permalink to &quot;The Thomas Schmid Chats&quot;">​</a></h2><p>Through thousands of messages, the WKStA was able to reconstruct how important posts in the state-owned companies (ÖBAG, CASAG) and ministries were filled.</p><h3 id="famous-quotes" tabindex="-1">Famous Quotes: <a class="header-anchor" href="#famous-quotes" aria-label="Permalink to &quot;Famous Quotes:&quot;">​</a></h3><ul><li><strong>&quot;Kriegst eh alles, was du willst&quot;</strong>: A promise of power that became a symbol of patronage (Postenschacher).</li><li><strong>&quot;Beinschab-Tool&quot;</strong>: The system for manipulating polls and media.</li><li><strong>&quot;Ich liebe meinen Kanzler&quot;</strong>: Testimony to the emotional and political dependence within the system.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>The Schmid chats are the &quot;language of power&quot; in our film. We contrast the polite, undercooled letters of Helmut Horten from the 1930s with the fast-paced, emoji-rich communication of the modern era.</p><ul><li><strong>Meta-Level:</strong> The chats show that power today is no longer exercised behind closed doors, but via WhatsApp – and that the digital traces of this power are just as difficult to erase as the &quot;Aryanized&quot; contracts of the past.</li></ul><hr><p><em>Sources: Chat protocols published by the WKStA, investigative dossiers of the Ibiza Committee of Inquiry.</em></p>',14)])])}const p=t(r,[["render",h]]);export{u as __pageData,p as default};
